"""Archivist Agent: Extracts possession windows and clutch moments into clips."""
from __future__ import annotations

import json
from pathlib import Path
from typing import Dict, Any, List

from src.common.video_utils import slice_video_clip


class ArchivistAgent:
    """Extracts short, focused action clips based on the timeline generated by Scorekeeper."""

    def __init__(self, output_dir: str | Path):
        self.output_dir = Path(output_dir)
        self.clips_dir = self.output_dir / "clips"
        self.clips_dir.mkdir(parents=True, exist_ok=True)

    def extract_possessions(
        self,
        video_path: str | Path,
        timeline_events_path: str | Path,
        lookback_sec: float = 14.0,
        follow_through_sec: float = 2.0
    ) -> List[Dict[str, Any]]:
        """Slices video windows leading up to each score change."""
        with open(timeline_events_path, "r", encoding="utf-8") as f:
            events = json.load(f)

        manifest: List[Dict[str, Any]] = []
        clip_index = 1

        for ev in events:
            if ev.get("type") == "SCORE_CHANGE":
                event_time = ev["timestamp_sec"]
                start_sec = max(0.0, event_time - lookback_sec)
                end_sec = event_time + follow_through_sec

                clip_name = f"possession_{clip_index:03d}.mp4"
                clip_path = self.clips_dir / clip_name

                slice_video_clip(video_path, clip_path, start_sec, end_sec)

                manifest.append({
                    "clip_id": f"POS_{clip_index:03d}",
                    "clip_file": clip_name,
                    "clip_path": str(clip_path),
                    "start_sec": start_sec,
                    "end_sec": end_sec,
                    "score_event": ev
                })
                clip_index += 1

        manifest_file = self.clips_dir / "manifest.json"
        with open(manifest_file, "w", encoding="utf-8") as f:
            json.dump(manifest, f, indent=2)

        return manifest
